<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { getApiBaseUrl } from '@/config/api'
import AdminSidebar from '@/components/admin/AdminSidebar.vue'

type Order = { reference: string; status: 'awaiting_transfer' | 'pending_payphone' | 'paid' | 'cancelled'; paymentMethod: 'payphone' | 'transfer'; totalCents: number; createdAt: string; hasTransferReceipt: boolean; invoice?: { identification: string; firstName: string; lastName: string; email: string; address: string }; buyer: { firstName: string; lastName: string; email: string; phone: string }; delivery: { city: string; province: string; address: string; reference: string } }
type Section = 'transfers' | 'all' | 'pending' | 'paid'
const router = useRouter()
const api = getApiBaseUrl()
const orders = ref<Order[]>([])
const section = ref<Section>('transfers')
const toast = ref('')
const isLoading = ref(true)
const money = (cents: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100)
const visibleOrders = computed(() => orders.value.filter((order) => section.value === 'all' || (section.value === 'transfers' && order.paymentMethod === 'transfer' && order.status === 'awaiting_transfer') || (section.value === 'pending' && order.status === 'pending_payphone') || (section.value === 'paid' && order.status === 'paid')))
const counts = computed(() => ({ transfers: orders.value.filter((order) => order.paymentMethod === 'transfer' && order.status === 'awaiting_transfer').length, pending: orders.value.filter((order) => order.status === 'pending_payphone').length, paid: orders.value.filter((order) => order.status === 'paid').length }))
function headers() { return { Authorization: `Bearer ${localStorage.getItem('access_token') || ''}`, 'Content-Type': 'application/json' } }
function notify(message: string) { toast.value = message; window.setTimeout(() => { toast.value = '' }, 3500) }
function setSection(value: Section | 'users') { if (value !== 'users') section.value = value }
function whatsappLink(order: Order) { const phone = order.buyer.phone.replace(/\D/g, ''); const international = phone.startsWith('593') ? phone : phone.startsWith('0') ? `593${phone.slice(1)}` : phone; return `https://wa.me/${international}?text=${encodeURIComponent(`Hola ${order.buyer.firstName}, te escribimos de OMG Lashes sobre tu pedido ${order.reference}.`)}` }
async function loadOrders() { isLoading.value = true; try { const response = await fetch(`${api}/orders/admin/list`, { headers: headers() }); const data = await response.json() as { orders?: Order[]; message?: string }; if (!response.ok) throw new Error(data.message || 'No pudimos cargar los pedidos.'); orders.value = data.orders || [] } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos cargar los pedidos.') } finally { isLoading.value = false } }
async function approveTransfer(order: Order) { try { const response = await fetch(`${api}/orders/admin/${encodeURIComponent(order.reference)}/status`, { method: 'PATCH', headers: headers(), body: JSON.stringify({ status: 'paid' }) }); const data = await response.json() as { message?: string }; if (!response.ok) throw new Error(data.message || 'No pudimos aprobar la transferencia.'); order.status = 'paid'; notify('Transferencia aprobada. Se envió el correo de confirmación al cliente.') } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos aprobar la transferencia.') } }
async function seeReceipt(order: Order) { try { const response = await fetch(`${api}/orders/admin/${encodeURIComponent(order.reference)}/receipt`, { headers: headers() }); const data = await response.json() as { url?: string; message?: string }; if (!response.ok || !data.url) throw new Error(data.message || 'No encontramos el comprobante.'); window.open(data.url, '_blank', 'noopener,noreferrer') } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos abrir el comprobante.') } }
onMounted(() => { const requested = router.currentRoute.value.query.section
  if (typeof requested === 'string' && ['transfers', 'pending', 'paid', 'all'].includes(requested)) section.value = requested as Section
  void loadOrders() })
</script>

<template>
  <main class="admin"><AdminSidebar :active="section" :counts="counts" @select="setSection" /><section class="content"><header class="content-header"><div class="header-title"><div><p>OPERACIÓN OMG</p><h1>{{ section === 'transfers' ? 'Transferencias por revisar.' : 'Pedidos y pagos.' }}</h1></div></div><button class="refresh" @click="loadOrders"><i class="fa-solid fa-rotate"></i> Actualizar</button></header><div class="stats"><span><b>{{ counts.transfers }}</b> transferencias por aprobar</span><span><b>{{ counts.pending }}</b> pagos PayPhone pendientes</span><span><b>{{ counts.paid }}</b> pagos confirmados</span></div><p v-if="isLoading" class="empty">Cargando pedidos...</p><p v-else-if="!visibleOrders.length" class="empty">No hay pedidos en esta sección.</p><div v-else class="orders"><article v-for="order in visibleOrders" :key="order.reference"><div class="order-head"><div><small>{{ new Date(order.createdAt).toLocaleString('es-EC') }}</small><h2>{{ order.reference }}</h2></div><strong :class="order.status">{{ order.status === 'paid' ? 'PAGADO' : order.status === 'awaiting_transfer' ? 'TRANSFERENCIA POR REVISAR' : 'PAGO PENDIENTE' }}</strong></div><div class="order-details"><p><b>Cliente</b>{{ order.buyer.firstName }} {{ order.buyer.lastName }}<a :href="`mailto:${order.buyer.email}`">{{ order.buyer.email }}</a></p><p><b>Entrega</b>{{ order.delivery.city }}, {{ order.delivery.province }}<span>{{ order.delivery.address }}</span></p><p><b>Total</b>{{ money(order.totalCents) }}<span>{{ order.paymentMethod === 'transfer' ? 'Transferencia bancaria' : 'PayPhone' }}</span></p></div><footer v-if="order.paymentMethod === 'transfer' && order.status === 'awaiting_transfer'"><button v-if="order.hasTransferReceipt" class="receipt" @click="seeReceipt(order)"><i class="fa-solid fa-receipt"></i> Ver comprobante</button><a :href="whatsappLink(order)" target="_blank" rel="noopener noreferrer"><i class="fa-brands fa-whatsapp"></i> Contactar cliente</a><button class="approve" :disabled="!order.hasTransferReceipt" @click="approveTransfer(order)"><i class="fa-solid fa-check"></i> Aprobar y enviar correo</button></footer></article></div></section><section v-if="visibleOrders.some((order) => order.invoice?.identification)" class="invoices"><p>FACTURACIÓN SOLICITADA</p><h2>Datos para emitir factura.</h2><article v-for="order in visibleOrders.filter((item) => item.invoice?.identification)" :key="`${order.reference}-invoice`"><header><b>{{ order.reference }}</b><span>{{ money(order.totalCents) }}</span></header><div><p><small>CÉDULA O RUC</small>{{ order.invoice?.identification }}</p><p><small>CLIENTE</small>{{ order.invoice?.firstName }} {{ order.invoice?.lastName }}</p><p><small>CORREO</small><a :href="`mailto:${order.invoice?.email}`">{{ order.invoice?.email }}</a></p><p><small>DIRECCIÓN</small>{{ order.invoice?.address }}</p></div></article></section><Transition name="toast"><div v-if="toast" class="toast">{{ toast }}</div></Transition></main>
</template>

<style scoped lang="scss">
.admin { --ink:#1D1D1B;--cream:#fbf7f2;--pink:#F1B9A9;--pink-soft:#F9E3DC;--gray:#55565A;--copper:#b86f54;background:var(--cream);color:var(--ink);font-family:Arial,sans-serif;min-height:100vh;overflow-x:hidden }.content { margin:auto;max-width:1400px;min-width:0;padding:30px 5vw 50px }@media (min-width:1025px) { .admin { padding-left:280px }.content { padding:44px 48px 60px } }.content-header { align-items:flex-start;display:flex;justify-content:space-between }.header-title { display:flex;flex-direction:column;gap:24px;min-width:0 }.content-header p { color:var(--copper);font-size:10px;letter-spacing:.12em;margin:0 0 9px }.content h1 { font:600 52px/.92 Georgia,serif;letter-spacing:-.07em;margin:0;max-width:580px }.refresh,.orders footer button,.orders footer a { align-items:center;background:var(--ink);border:0;color:var(--cream);cursor:pointer;display:flex;font:600 11px Arial,sans-serif;gap:8px;letter-spacing:.05em;padding:13px 15px;text-decoration:none;text-transform:uppercase }.stats { display:flex;flex-wrap:wrap;gap:12px;margin:35px 0 25px }.stats span { background:var(--pink);font-size:12px;padding:14px }.stats b { font-size:18px }.orders { display:flex;flex-direction:column;gap:16px;min-width:0 }.orders article { background:#fffdfa;border:1px solid #e1d6d0;min-width:0;padding:22px }.order-head { align-items:start;border-bottom:1px solid #eaded8;display:flex;gap:14px;justify-content:space-between;padding-bottom:16px }.order-head>div,.order-details p { min-width:0 }.order-head small { color:#77787B;font-size:10px }.order-head h2 { font:600 19px Georgia,serif;margin:6px 0 0;overflow-wrap:anywhere;word-break:break-word }.order-head strong { font-size:10px;letter-spacing:.06em;padding:7px 9px;word-break:break-word }.order-head strong.paid { background:#d9ecdd;color:#216335 }.order-head strong.awaiting_transfer,.order-head strong.pending_payphone { background:#f7e4bc;color:#7b5110 }.order-details { display:flex;gap:26px;padding:19px 0 }.order-details p { display:flex;flex:1;flex-direction:column;font-size:13px;gap:6px;line-height:1.35;margin:0;overflow-wrap:anywhere }.order-details b { color:var(--copper);font-size:10px;letter-spacing:.07em;text-transform:uppercase }.order-details a { color:var(--ink);overflow-wrap:anywhere }.order-details span { color:#77787B }.orders footer { align-items:center;border-top:1px solid #eaded8;display:flex;flex-wrap:wrap;gap:10px;padding-top:16px }.orders footer a { background:transparent;border:1px solid var(--ink);color:var(--ink) }.orders footer .approve { background:#216335 }.approve:disabled { cursor:not-allowed;opacity:.45 }.invoices { background:var(--ink);color:#fffdfa;margin:34px 0 0;padding:32px }.invoices>p { color:#d39986;font:600 10px Arial,sans-serif;letter-spacing:.12em;margin:0 0 8px }.invoices h2 { font:600 30px Georgia,serif;letter-spacing:-.05em;margin:0 0 22px }.invoices article { background:#fffdfa;color:var(--ink);margin-top:12px;min-width:0;padding:18px }.invoices article header { align-items:center;border-bottom:1px solid #e1d6d0;display:flex;gap:12px;justify-content:space-between;padding-bottom:12px }.invoices article header b { font:600 15px Georgia,serif;overflow-wrap:anywhere }.invoices article header span { color:var(--copper);font:600 13px Arial,sans-serif }.invoices article>div { display:flex;flex-wrap:wrap;gap:18px;padding-top:14px }.invoices article p { display:flex;flex:1 1 190px;flex-direction:column;font-size:13px;gap:5px;margin:0;overflow-wrap:anywhere }.invoices small { color:var(--copper);font:600 9px Arial,sans-serif;letter-spacing:.07em }.invoices a { color:var(--ink);overflow-wrap:anywhere }.empty { color:#77787B;margin-top:55px }.toast { background:var(--ink);bottom:24px;color:var(--cream);font-size:12px;left:50%;padding:14px 18px;position:fixed;transform:translateX(-50%);z-index:30 }.backdrop-enter-active,.backdrop-leave-active { transition:opacity .25s ease }.backdrop-enter-from,.backdrop-leave-to { opacity:0 }@media (max-width:700px) { .content { padding:22px 18px 36px }.content-header { flex-direction:column;gap:20px }.content h1 { font-size:42px }.order-head { flex-direction:column }.order-head strong { align-self:flex-start }.order-details { flex-direction:column;gap:16px }.orders footer { align-items:stretch;flex-direction:column }.orders footer button,.orders footer a { justify-content:center;width:100% }.invoices { margin-top:24px;padding:25px 18px }.invoices article>div { flex-direction:column;gap:14px } }
</style>
